// Generated by AI
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import type { Operation, OperationResult } from '@felan-ai/session-protocol';
import * as supervisor from '@felan-ai/daemon/client';
import { identityFor } from '../../daemon/src/daemon/target.js';
import { SessionClient, type SessionClientOptions } from '../src/client/client.js';
import type { TransportConnector } from '../src/client/transport.js';
import { FakeTransport, snapshot } from './client-fixtures.js';

type Composition = NonNullable<OperationResult<'hello'>['composition']>;
const composition = (): Composition => ({ managerPackage: '@felan-ai/felan', managerVersion: 'installed',
  providerDigest: 'a'.repeat(64), configDigest: 'b'.repeat(64) });
const clients: SessionClient[] = [];
const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  for (const client of clients.splice(0)) client.close();
  await Promise.all(roots.splice(0).map(path => rm(path, { recursive: true, force: true })));
});

async function fixture(options: Partial<SessionClientOptions> = {}, pinned = false) {
  const directory = await mkdtemp(join(tmpdir(), 'client-build-')); roots.push(directory);
  const target = { kind: 'isolated', directory, namespaceId: 'client-build' } as const;
  const identity = identityFor(supervisor.resolveDaemonTarget(target), 'instance');
  const fake = new FakeTransport();
  const client = new SessionClient({ target, kind: 'tui', clientVersion: 'installed', expectedDaemonVersion: 'installed',
    expectedComposition: composition(), requestTimeoutMs: 20, retries: 0, reconnectAttempts: 0, reconnectDelayMs: 0,
    connector: fake.connector, ...options, ...(pinned ? { expected: identity } : {}) });
  clients.push(client);
  const host = { identity, daemonVersion: 'installed', composition: composition() as Composition | undefined, work: 1,
    operations: ['attach', 'host.status'] as Operation[], statusReply: 'accepted' as 'accepted' | 'rejected' | 'timeout',
    onRestart: () => {} };
  fake.onSend = (request, connection) => {
    if ('control' in request) {
      const control = request as { id: string; op: string };
      if (control.op === 'host.restart') host.onRestart();
      fake.frame({ control: 1, re: control.id, identity: host.identity, daemonVersion: host.daemonVersion, supportedProtocol: 1,
        state: control.op === 'host.restart' ? 'draining' : 'stopped', outcome: 'accepted' }, connection);
    } else if (request.op === 'hello') {
      fake.reply(request, { attachmentId: `hello-${connection}`, principal: 'principal', daemonVersion: host.daemonVersion,
        protocol: 1, identity: host.identity, operations: host.operations, interactionKinds: [],
        ...(host.composition ? { composition: host.composition } : {}) }, connection);
    } else if (request.op === 'host.status') {
      if (host.statusReply === 'accepted') fake.reply(request, { identity: host.identity, daemonVersion: host.daemonVersion,
        protocol: 1, state: 'ready', active: { sessions: 1, runs: 0, work: host.work, attachments: 1 }, setupNeeds: [] }, connection);
      else if (host.statusReply === 'rejected') fake.frame({ v: 1, re: request.id, outcome: 'rejected',
        error: { code: 'unavailable', message: 'Unavailable', retryable: false } }, connection);
    } else if (request.op === 'attach') fake.reply(request, { attachmentId: `binding-${connection}`, snapshot: snapshot() }, connection);
  };
  return { client, fake, host, target };
}

describe('daemon build compatibility', () => {
  it.each(['managerPackage', 'managerVersion', 'providerDigest', 'configDigest', 'absent'] as const)(
    'attaches across %s composition differences without restarting', async field => {
      const { client, fake, host } = await fixture({ launch: { entrypoint: '/fixture/entrypoint.js' } });
      host.work = 0;
      if (field === 'absent') host.composition = undefined;
      else host.composition![field] = field.endsWith('Digest') ? 'd'.repeat(64) : '@other/manager';
      await client.connect();
      expect((await client.attach('session')).outcome).toBe('accepted');
      expect(client.status).toBe('ready'); expect(fake.controls).toEqual([]);
      if (field !== 'configDigest') expect(client.buildMismatch).toBeDefined();
    });

  it.each(['different', 'absent'] as const)('attaches to an old daemon with %s composition', async metadata => {
    const { client, fake, host } = await fixture();
    host.daemonVersion = 'previous'; host.work = 0;
    host.composition = metadata === 'absent' ? undefined : { ...composition(), managerPackage: '@other/manager',
      managerVersion: 'previous', providerDigest: 'd'.repeat(64), configDigest: 'e'.repeat(64) };
    await client.connect();
    expect((await client.attach('session')).outcome).toBe('accepted');
    expect(client.buildMismatch?.daemonVersion).toBe('previous');
    expect(fake.controls).toEqual([]);
  });

  it('attaches to a busy different build and exposes copied build details', async () => {
    const expectedComposition = composition();
    const { client, fake, host } = await fixture({ expectedComposition, launch: { entrypoint: '/fixture/entrypoint.js' } });
    host.daemonVersion = 'previous'; host.composition!.managerVersion = 'previous'; host.composition!.providerDigest = 'd'.repeat(64);
    expectedComposition.managerVersion = 'mutated';
    await client.connect();
    expect((await client.attach('session')).outcome).toBe('accepted');
    expect(client.status).toBe('ready'); expect(client.incompatibleActiveWork).toBeUndefined();
    expect(client.buildMismatch).toEqual({ daemonVersion: 'previous', expectedDaemonVersion: 'installed', activeWork: 1,
      composition: host.composition, expectedComposition: composition() });
    const copy = client.buildMismatch!;
    (copy.composition as Composition).managerVersion = 'mutated';
    (copy.expectedComposition as Composition).managerVersion = 'mutated';
    expect(client.buildMismatch?.composition?.managerVersion).toBe('previous');
    expect(client.buildMismatch?.expectedComposition?.managerVersion).toBe('installed');
    expect(fake.controls).toEqual([]);
  });

  it.each(['managerVersion', 'providerDigest'] as const)('reports a differing %s even when daemon versions match', async field => {
    const { client, host } = await fixture();
    host.composition![field] = field === 'managerVersion' ? 'previous' : 'd'.repeat(64);
    await client.connect();
    expect(client.status).toBe('ready');
    expect(client.buildMismatch).toMatchObject({ daemonVersion: 'installed', expectedDaemonVersion: 'installed',
      composition: { [field]: host.composition![field] } });
  });

  it('does not treat a build-dependent config digest alone as a mismatch', async () => {
    const { client, host, fake } = await fixture();
    host.composition!.configDigest = 'd'.repeat(64);
    await client.connect();
    expect(client.status).toBe('ready'); expect(client.buildMismatch).toBeUndefined();
    expect(fake.requests.map(request => request.op)).toEqual(['hello']);
  });

  it.each(['unsupported', 'rejected', 'timeout'] as const)('attaches when active work is unknown because status is %s', async reason => {
    const { client, fake, host } = await fixture({ launch: { entrypoint: '/fixture/entrypoint.js' } });
    host.daemonVersion = 'previous'; host.work = 0;
    if (reason === 'unsupported') host.operations = ['attach']; else host.statusReply = reason;
    await client.connect();
    expect(client.status).toBe('ready'); expect(client.buildMismatch?.daemonVersion).toBe('previous');
    expect(client.buildMismatch?.activeWork).toBeUndefined(); expect(fake.controls).toEqual([]);
  });

  it.each(['no-launch', 'pinned'] as const)('attaches to an idle old build without replacement authority: %s', async authority => {
    const launch = vi.spyOn(supervisor, 'spawnDetachedDaemon');
    const { client, fake, host } = await fixture(authority === 'pinned' ? { launch: { entrypoint: '/fixture/entrypoint.js' } } : {}, authority === 'pinned');
    host.daemonVersion = 'previous'; host.work = 0;
    await client.connect();
    expect(client.status).toBe('ready'); expect(client.buildMismatch).toMatchObject({ daemonVersion: 'previous', activeWork: 0 });
    expect(fake.controls).toEqual([]); expect(launch).not.toHaveBeenCalled();
  });

  it.each(['matching', 'different'] as const)('replaces an idle initial build once, then attaches to a %s replacement build', async replacement => {
    const { client, fake, host } = await fixture({ launch: { entrypoint: '/fixture/entrypoint.js' } });
    host.daemonVersion = 'previous'; host.work = 0;
    host.onRestart = () => { host.daemonVersion = replacement === 'matching' ? 'installed' : 'another'; };
    await client.connect();
    expect(client.status).toBe('ready');
    expect(fake.controls).toMatchObject([{ op: 'host.restart', params: { mode: 'drain' } }, { op: 'host.status' }]);
    expect(fake.requests.filter(request => request.op === 'hello')).toHaveLength(2);
    if (replacement === 'matching') expect(client.buildMismatch).toBeUndefined();
    else expect(client.buildMismatch).toMatchObject({ daemonVersion: 'another', activeWork: 0 });
  });

  it('launches only once after draining even when the replacement receipt names another build', async () => {
    let connector!: TransportConnector;
    const { client, fake, host, target } = await fixture({ launch: { entrypoint: '/fixture/entrypoint.js' },
      connector: receiver => connector(receiver) });
    connector = fake.connector;
    host.daemonVersion = 'previous'; host.work = 0;
    const previous = structuredClone(host.identity);
    const missing = Object.assign(new Error('missing'), { code: 'ENOENT' });
    host.onRestart = () => { connector = async () => { throw missing; }; };
    vi.spyOn(supervisor, 'connectLocalIpc').mockRejectedValue(missing);
    const launch = vi.spyOn(supervisor, 'spawnDetachedDaemon').mockImplementation(async () => {
      connector = fake.connector; host.daemonVersion = 'another'; host.identity = { ...previous, instanceId: 'replacement' };
      return { target, identity: host.identity, daemonVersion: host.daemonVersion };
    });
    await client.connect();
    expect(client.status).toBe('ready'); expect(client.identity).toEqual(host.identity);
    expect(client.buildMismatch).toMatchObject({ daemonVersion: 'another', activeWork: 0 });
    expect(launch).toHaveBeenCalledExactlyOnceWith({ target, entrypoint: '/fixture/entrypoint.js', replacing: previous });
    expect(fake.controls).toMatchObject([{ op: 'host.restart', params: { mode: 'drain' } }]);
  });

  it.each(['automatic', 'manual'] as const)('an old client follows a new idle build on %s reconnect without restarting it', async reconnect => {
    const launch = vi.spyOn(supervisor, 'spawnDetachedDaemon');
    const { client, fake, host } = await fixture({ launch: { entrypoint: '/fixture/entrypoint.js' },
      reconnectAttempts: reconnect === 'automatic' ? 1 : 0 });
    await client.connect(); await client.attach('session');
    host.daemonVersion = 'newer'; host.composition!.managerVersion = 'newer'; host.composition!.providerDigest = 'd'.repeat(64);
    host.identity = { ...host.identity, instanceId: 'restarted' }; host.work = 0;
    const statuses: string[] = [];
    client.subscribe(() => statuses.push(client.status));
    fake.lose();
    if (reconnect === 'manual') await client.connect(); else await vi.waitFor(() => expect(client.status).toBe('ready'));
    expect(client.identity).toEqual(host.identity); expect(client.getAttachment('session')?.state.status).toBe('live');
    expect(client.buildMismatch).toMatchObject({ daemonVersion: 'newer', expectedDaemonVersion: 'installed', activeWork: 0 });
    expect(statuses).not.toContain('incompatible'); expect(fake.controls).toEqual([]); expect(launch).not.toHaveBeenCalled();
  });

  it('clears stale warnings during a reconnect, on matching builds, on failure and on close', async () => {
    const { client, fake, host } = await fixture();
    const identity = host.identity;
    expect(client.buildMismatch).toBeUndefined();
    host.daemonVersion = 'previous'; await client.connect();
    expect(client.buildMismatch).toBeDefined(); fake.lose(); expect(client.buildMismatch).toBeUndefined();
    const warnings: unknown[] = [];
    client.subscribe(() => { if (client.status !== 'ready') warnings.push(client.buildMismatch); });
    host.daemonVersion = 'installed'; await client.connect(); expect(client.buildMismatch).toBeUndefined();
    fake.lose(); host.daemonVersion = 'previous'; await client.connect(); expect(client.buildMismatch).toBeDefined();
    fake.lose(); host.statusReply = 'timeout'; host.identity = { ...host.identity, namespaceId: 'wrong' };
    await expect(client.connect()).rejects.toThrow(); expect(client.buildMismatch).toBeUndefined();
    host.identity = identity;
    host.composition = composition(); await client.connect(); expect(client.buildMismatch).toBeDefined();
    client.close(); expect(client.buildMismatch).toBeUndefined();
    expect(warnings.length).toBeGreaterThan(0); expect(warnings.every(warning => warning === undefined)).toBe(true);
  });

  it('retains identity checks when the build is otherwise compatible', async () => {
    const { client, host } = await fixture({}, true);
    host.daemonVersion = 'previous'; host.identity = { ...host.identity, instanceId: 'unexpected' };
    await expect(client.connect()).rejects.toThrow(/pinned target/);
    expect(client.status).toBe('blocked'); expect(client.buildMismatch).toBeUndefined();
  });

});
